glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
out float v_time;
in vec2 a_uv0;
out vec2 v_uv0;
void main () {
  vec4 pos = vec4(a_position, 1.0);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  v_uv0 = a_uv0;
  v_color = a_color;
  v_time = cc_time.x;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
in float v_time;
in vec2 v_uv0;
#if USE_TEXTURE
uniform sampler2D texture;
#endif
uniform sampler2D flowTexture;
uniform Constant {
  float windowSize;
  float speed;
  float slope;
  float windowOffset;
};
void main () {
  vec4 maskColor = vec4(1.0, 1.0, 1.0, 1.0);
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    maskColor.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    maskColor.a *= texture_tmp.a;
  #else
    maskColor *= texture_tmp;
  #endif
  #endif
  float safeWindowSize = max(windowSize, 0.0001);
  float windowBase = fract(windowOffset - v_time * speed);
  float flowU = fract(windowBase + (v_uv0.x + v_uv0.y * slope) * safeWindowSize);
  vec4 flowColor = vec4(1.0, 1.0, 1.0, 1.0);
  vec4 flowTexture_tmp = texture(flowTexture, vec2(flowU, 0.5));
  #if CC_USE_ALPHA_ATLAS_flowTexture
      flowTexture_tmp.a *= texture(flowTexture, vec2(flowU, 0.5) + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    flowColor.rgb *= (flowTexture_tmp.rgb * flowTexture_tmp.rgb);
    flowColor.a *= flowTexture_tmp.a;
  #else
    flowColor *= flowTexture_tmp;
  #endif
  vec4 o = vec4(1.0, 1.0, 1.0, 1.0);
  o.rgb = flowColor.rgb * v_color.rgb;
  o.a = flowColor.a * maskColor.a * v_color.a;
  ALPHA_TEST(o);
  #if USE_BGRA
    gl_FragColor = o.bgra;
  #else
    gl_FragColor = o.rgba;
  #endif
}

